package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarUtils_parseOctal_TriageGen1Test {

    @Test
    public void testParseOctal_ValidSimple() {
        byte[] buffer = "000123 ".getBytes();
        // length 7, end is 7. trailer at buffer[7] is invalid in real array, 
        // but let's simulate the buffer size to accommodate the logic.
        byte[] paddedBuffer = new byte[8];
        System.arraycopy(buffer, 0, paddedBuffer, 0, 7);
        paddedBuffer[7] = 0; // NUL trailer

        long result = TarUtils.parseOctal(paddedBuffer, 0, 7);
        assertEquals(83L, result); // 123 octal = 83 decimal
    }

    @Test
    public void testParseOctal_AllNUL() {
        byte[] buffer = new byte[5]; // all 0
        long result = TarUtils.parseOctal(buffer, 0, 5);
        assertEquals(0L, result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_LengthTooShort() {
        byte[] buffer = new byte[1];
        TarUtils.parseOctal(buffer, 0, 1);
    }

    @Test
    public void testParseOctal_LeadingSpaces() {
        byte[] buffer = "   755 ".getBytes();
        byte[] paddedBuffer = new byte[8];
        System.arraycopy(buffer, 0, paddedBuffer, 0, 7);
        paddedBuffer[7] = 0;

        long result = TarUtils.parseOctal(paddedBuffer, 0, 7);
        assertEquals(493L, result); // 755 octal = 493 decimal
    }

    @Test
    public void testParseOctal_TrailingNULAndSpace() {
        // Test logic: trailer = buffer[end/1]; if trailer == 0 || ' ', end--
        // and then trailer = buffer[end-1]; if trailer == 0 || ' ', end--
        byte[] buffer = "123  0".getBytes(); // "123" + space + space + NUL
        // length 6. end=6. buffer[6] is 0. end becomes 5. buffer[4] is ' '. end becomes 4.
        long result = TarUtils.parseOctal(buffer, 0, 6);
        assertEquals(83L, result);
    }

    @Test
    public void testParseOctal_SingleTrailingSpace() {
        byte[] buffer = "123 ".getBytes();
        byte[] paddedBuffer = new byte[5];
        System.arraycopy(buffer, 0, paddedBuffer, 0, 4);
        paddedBuffer[4] = 'X'; // Something else to avoid index out of bounds if logic allows

        // length 4. end=4. buffer[4] is 'X'. This should trigger exception.
        // However, the method uses buffer[end/1]. If length is 4, end is 4. 
        // We need buffer to be at least size 5.
        try {
            TarUtils.parseOctal(paddedBuffer, 0, 4);
            fail("Expected IllegalArgumentException due to invalid trailer");
        } catch (IllegalArgumentException e) {
            // Success
        }
    }

    @Test
    public void testParseOctal_ValidTrailingSpaceOnly() {
        byte[] buffer = "777 ".getBytes();
        byte[] paddedBuffer = new byte[5];
        System.arraycopy(buffer, 0, paddedBuffer, 0, 4);
        paddedBuffer[4] = 0; // The trailer check is buffer[end]

        // length 4. end=4. buffer[4] is 0. end becomes 3.
        // buffer[2] is '7'. end stays 3.
        long result = TarUtils.parseOctal(paddedBuffer, 0, 4);
        assertEquals(511L, result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidDigit() {
        byte[] buffer = "128 ".getBytes(); // 8 is not octal
        byte[] paddedBuffer = new byte[5];
        System.arraycopy(buffer, 0, paddedBuffer, 0, 4);
        paddedBuffer[4] = 0;
        TarUtils.parseOctal(paddedBuffer, 0, 4);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_NonDigitChar() {
        byte[] buffer = "12A ".getBytes();
        byte[] paddedBuffer = new byte[5];
        System.arraycopy(buffer, 0, paddedBuffer, 0, 4);
        paddedBuffer[4] = 0;
        TarUtils.parseOctal(paddedBuffer, 0, 4);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidTrailer() {
        byte[] buffer = "123X".getBytes();
        // length 4. end=4. buffer[4] is out of bounds if we don't pad.
        byte[] paddedBuffer = new byte[5];
        System.arraycopy(buffer, 0, paddedBuffer, 0, 4);
        paddedBuffer[4] = 'Z'; 

        TarUtils.parseOctal(paddedBuffer, 0, 4);
    }

    @Test
    public void testParseOctal_OffsetUsage() {
        byte[] buffer = "ABC 123 ";
        byte[] paddedBuffer = new byte[10];
        System.arraycopy(buffer, 0, paddedBuffer, 0, 8);
        paddedBuffer[8] = 0; // trailer

        // offset 4, length 4 -> " 123"
        // start=4. buffer[4] is ' '. start becomes 5.
        // end=8. buffer[8] is 0. end becomes 7.
        // buffer[6] is '3'. end stays 7.
        // loop start=5 to end=7 -> buffer[5]='1', buffer[6]='2'... wait.
        // Let's trace: " 123 " length 5. offset 3.
        byte[] buf2 = "  123 0".getBytes();
        // offset 2, length 5. end=7. buffer[7] is 0. end becomes 6.
        // buffer[5] is ' '. end becomes 5.
        // start=2. buffer[2]='1', buffer[3]='2', buffer[4]='3'.
        long result = TarUtils.parseOctal(buf2, 2, 5);
        assertEquals(83L, result);
    }
}
